selector { }
.balance {
    text-wrap: balance;
}

.gold, .gradient {
    background-image: linear-gradient(90deg, #0077B6, #00B4D8);
    color: transparent;
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
}

.cta-button .elementor-button {
    text-decoration: none;
    border: none;
    cursor: pointer;
    position: relative;
    overflow: hidden;
    transition: transform 0.3s ease, box-shadow 0.3s ease, outline 0.3s ease;
    outline: 2px solid transparent;
}

.cta-button .elementor-button::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
    transition: left 0.5s ease;
}

.cta-button .elementor-button:hover {
    transform: translateY(-3px);
    box-shadow: 0 20px 40px rgba(0,180,216,0.35);
    outline: 2px solid #90E0EF;
    outline-offset: 4px;
}

.cta-button .elementor-button:hover::before {
    left: 100%;
}

.cta-button .elementor-button-icon {
    transition: transform 0.3s ease;
}

.cta-button .elementor-button:hover .elementor-button-icon {
    transform: translateX(4px);
}

html::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: radial-gradient(at 20% 80%, #fff 1px, transparent 0px);
    background-size: 3px 3px;
    pointer-events: none;
    z-index: 999;
    opacity: 0.05;
    mix-blend-mode: plus-lighter;
    user-select: none;
}
